steps.code:
# We have the queue and downloaded songs. Let's define the downloaded song IDs set and then advance through the queue.
downloaded_ids = {song['song_id'] for song in downloaded}
print("Downloaded IDs:", downloaded_ids)

# Current song is at position 5 (song 322). We'll call next_song repeatedly until we hit a downloaded song.
for step in range(10):
    result = apis.spotify.next_song(access_token=access_token)
    print(f"Step {step+1}: next_song returned {result}")
    new_song_id = result.get('song_id')
    if new_song_id in downloaded_ids:
        print(f"Reached downloaded song {new_song_id}!")
        break
else:
    print("Did not find a downloaded song within 10 steps.")

