# Remove matched songs from all playlists that contain them
for playlist in all_playlists:
    pid = playlist['playlist_id']
    for song_id in playlist['song_ids']:
        if song_id in matched_song_ids:
            result = apis.spotify.remove_song_from_playlist(playlist_id=pid, song_id=song_id, access_token=spotify_token)
            print(f"Removed song {song_id} from playlist {pid}: {result}")

# Add all matched songs to the new "Archived Songs" playlist (ID 654)
for song_id in matched_song_ids:
    result = apis.spotify.add_song_to_playlist(playlist_id=654, song_id=song_id, access_token=spotify_token)
    print(f"Added song {song_id} to playlist 654: {result}")

