steps.code:
# Let's search for each song and find the exact match by title and artists.
old_song_ids = []
for song in songs:
    search_result = apis.spotify.search_songs(query=song['title'], access_token=spotify_login['access_token'])
    # Find the song that matches title and all artists
    matched = None
    for s in search_result:
        if s['title'].lower() == song['title'].lower():
            # Check if all artists in the song match
            artist_names = [a['name'].lower() for a in s['artists']]
            expected_artists = [a.lower() for a in song['artists']]
            if all(exp in artist_names for exp in expected_artists) and len(artist_names) == len(expected_artists):
                matched = s
                break
    if matched:
        old_song_ids.append(matched['song_id'])
        print(f"Found: {song['title']} -> song_id {matched['song_id']}")
    else:
        print(f"NOT FOUND: {song['title']}")

print(f"\nTotal old songs found: {len(old_song_ids)}")

