steps.code:
# Define the set of song IDs to archive based on the file content and search results
archive_song_ids = {295, 324, 22, 245, 320, 92, 299, 4, 278, 69, 219, 298, 265}
print("Songs to archive:", sorted(archive_song_ids))

# Compute which songs to remove from each playlist
removals = {}
for pl in playlists:
    pl_id = pl['playlist_id']
    to_remove = [sid for sid in pl['song_ids'] if sid in archive_song_ids]
    if to_remove:
        removals[pl_id] = to_remove
print(removals)

# Remove the matching songs from each playlist
for pl_id, song_ids in removals.items():
    for sid in song_ids:
        result = apis.spotify.remove_song_from_playlist(playlist_id=pl_id, song_id=sid, access_token=spotify_token)
        print(f"Removed song {sid} from playlist {pl_id}: {result}")

