# Fetch all playlists' songs to identify which contain old songs
old_song_ids = {295, 324, 22, 245, 320, 92, 299, 4, 278, 69, 219, 298, 265}
playlist_ids = [p["playlist_id"] for p in playlists]
playlist_songs = {}
for pid in playlist_ids:
    pl = apis.spotify.show_playlist(playlist_id=pid, access_token=spotify_token)
    song_ids = [s["id"] for s in pl.get("songs", [])]
    playlist_songs[pid] = song_ids
    print(f"Playlist {pid} ({pl.get('title')}): {song_ids}")

