# Extract release months from saved results for the first 8 songs
import datetime

# Define the mapping of song titles to their release dates from saved results
song_release_dates = {}

# Tangled Lies from _mem['s19']
for song in _mem['s19']:
    if song['title'] == 'Tangled Lies':
        song_release_dates['Tangled Lies'] = song['release_date']
        break

# Lost in the Wilderness of Love from _mem['s20']
for song in _mem['s20']:
    if song['title'] == 'Lost in the Wilderness of Love':
        song_release_dates['Lost in the Wilderness of Love'] = song['release_date']
        break

# Lost in the Twilight of Hope from _mem['s21']
for song in _mem['s21']:
    if song['title'] == 'Lost in the Twilight of Hope':
        song_release_dates['Lost in the Twilight of Hope'] = song['release_date']
        break

# The Distance Between Two Hearts from _mem['s22']
for song in _mem['s22']:
    if song['title'] == 'The Distance Between Two Hearts':
        song_release_dates['The Distance Between Two Hearts'] = song['release_date']
        break

# When All Hope Seems Lost from _mem['s23']
for song in _mem['s23']:
    if song['title'] == 'When All Hope Seems Lost':
        song_release_dates['When All Hope Seems Lost'] = song['release_date']
        break

# The Forgotten Pages of Time from _mem['s24']
for song in _mem['s24']:
    if song['title'] == 'The Forgotten Pages of Time':
        song_release_dates['The Forgotten Pages of Time'] = song['release_date']
        break

# Summer's End from _mem['s25']
for song in _mem['s25']:
    if song['title'] == "Summer's End":
        song_release_dates["Summer's End"] = song['release_date']
        break

# Whispers of a Forgotten Love - we need to find it. It was in _mem['s20']? Actually summary says it was found. Let's check _mem['s20'] again.
# Actually _mem['s20'] was for Lost in the Wilderness of Love, but maybe Whispers was also in that search? Let's check.
# We'll search all saved results for it.
for key in ['s19','s20','s21','s22','s23','s24','s25']:
    for song in _mem[key]:
        if song['title'] == 'Whispers of a Forgotten Love':
            song_release_dates['Whispers of a Forgotten Love'] = song['release_date']
            break

# Print the mapping
print(song_release_dates)

