steps.code:
# Search for each TODO song and find the matching release date
import re

# We'll store results: song_title -> release_date string
release_dates = {}

for song in todo_songs:
    title = song['title']
    artists = song['artists']
    # Search by title
    search_res = apis.spotify.search_songs(query=title, access_token=spotify_token)
    # Find the matching song: title exact match and all artists present
    matched = None
    for s in search_res:
        if s['title'].lower() == title.lower():
            # Check artists
            result_artists = {a['name'].lower() for a in s['artists']}
            note_artists = {a.lower() for a in artists}
            if note_artists.issubset(result_artists) and len(note_artists) == len(result_artists):
                matched = s
                break
    if matched:
        release_dates[title] = matched['release_date']
        print(f"{title} -> {matched['release_date']} (song_id={matched['song_id']})")
    else:
        print(f"WARNING: No exact match for {title} by {artists}")

print("\nAll release dates found:", len(release_dates))

